from ta_moler.cmd.netactnode.genericnetactnode import GenericNetActNodeCommand
from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
import re

__author__ = 'Lukasz Micor'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'lukasz.micor@nokia.com'


class Sosreport(GenericNetActNodeCommand):
    """Sosreport command class."""

    def __init__(self, connection, options="", initial_name="", last_name="", case_id="", prompt=None,
                 newline_chars=None, runner=None):
        """
        Represent Unix command sosreport.

        :param connection: moler connection to device, terminal when command is executed
        :param options: parameter with which the command will be executed
        :param initial_name: initial name to generate logs
        :param last_name: last name to generate logs
        :param case_id: case id to generate logs
        :param prompt: prompt (on system where command runs).
        :param newline_chars: characters to split lines
        :param runner: Runner to run command
        """
        super(Sosreport, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                        runner=runner)
        self.current_ret["LOGS_FILE_PATH"] = None
        self.options = options

        self.initial_name = initial_name
        self.last_name = last_name
        self.case_id = case_id
        self._send_enter = False
        self._send_case_id = False
        self._send_initial_last_name = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "sosreport"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise.
        :return: None.
        """
        try:
            self._parse_error(line)
            self._push_enter(line)
            self._push_initial_last_name(line)
            self._push_initial_case_id(line)
            self._parse_create_logs_file_name(line)
            self._parse_success(line)
        except ParsingDone:
            pass

        return super(Sosreport, self).on_new_line(line, is_full_line)

    def _push_enter(self, line):
        """
        Send enter as accept of collecting logs.

        :param line: Line from device.
        :return: None.
        """
        if self._parse_continue_collecting_logs(line) and (not self._send_enter):
            self.connection.sendline('')
            self._send_enter = True

    # Press ENTER to continue, or CTRL-C to quit.
    _re_continue_collecting = re.compile(r'Press ENTER to continue, or CTRL-C to quit.')

    def _parse_continue_collecting_logs(self, line):
        """
        Parse continue collecting logs.

        :param line: Line from device.
        :return: None.
        """
        return self._regex_helper.search_compiled(Sosreport._re_continue_collecting, line)

    def _push_initial_last_name(self, line):
        """
        Send initial and last name.

        :param line: Line from device.
        :return: None.
        """
        if self._parse_enter_initial_last_name(line) and (not self._send_initial_last_name):
            self.connection.sendline(f'{self.initial_name}{self.last_name}')
            self._send_initial_last_name = True

    # Please enter your first initial and last name [clab1364node19]:
    _re_initial_last_name = re.compile(r'Please enter your first initial and last name \[(clab|coop)\d+node\d+\]: ')

    def _parse_enter_initial_last_name(self, line):
        """
        Parse enter initial last name.

        :param line: Line from device.
        :return: Result of match.
        """
        return self._regex_helper.search_compiled(Sosreport._re_initial_last_name, line)

    def _push_initial_case_id(self, line):
        """
        Send case id.

        :param line: Line from device.
        :return: None
        """
        if self._parse_enter_case_id(line) and (not self._send_case_id):
            self.connection.sendline(f'{self.case_id}')
            self._send_case_id = True

    # Please enter the case id that you are generating this report for []:
    _re_case_id = re.compile(r'Please enter the case id that you are generating this report for \[.*\]: ')

    def _parse_enter_case_id(self, line):
        """
        Parse enter case id.

        :param line: Line from device.
        :return: Result of match.
        """
        return self._regex_helper.search_compiled(Sosreport._re_case_id, line)

    # Please send this file to your support representative.
    _re_parse_success = re.compile(r'Please send this file to your support representative.')

    def _parse_success(self, line):
        """
        Parse line if success.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches success.
        """
        if self._regex_helper.search_compiled(Sosreport._re_parse_success, line):
            raise ParsingDone

    # /var/tmp/sosreport-clab1364node19-20190411161224.tar.xz
    _re_parse_logs_path = re.compile(r'(?P<FILE_PATH>(/[a-zA-Z0-9._-]+)+tar.xz)')

    def _parse_create_logs_file_name(self, line):
        """
        Parse path to collected logs.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches path to collected logs.
        """
        if self._regex_helper.search_compiled(Sosreport._re_parse_logs_path, line):
            self.current_ret['LOGS_FILE_PATH'] = self._regex_helper.group('FILE_PATH')
            raise ParsingDone

    # error: no such option: -r
    _re_parse_error = re.compile(r'(?P<ERROR>error: no such option:.*)')

    def _parse_error(self, line):
        """
        Parse line if error.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches error.
        """
        if self._regex_helper.search_compiled(Sosreport._re_parse_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone


